def fibonacci_recursive(n):
    # Проверяем, является ли n неотрицательным целым числом
    if not isinstance(n, int) or n < 0:
        raise ValueError("n должен быть целым неотрицательным числом")
    # Если n равно 0 или 1, возвращаем n (базовый случай)
    elif n <= 1:
        return n
    # Для всех остальных значений n.call fibonacci_recursive(n-1) + fibonacci_recursive(n-2)
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)
