class Node:
    """Represents a node in the binary search tree."""
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinarySearchTree:
    """Represents a binary search tree."""
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Inserts a node with the given value into the binary search tree."""
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert(self.root, value)

    def _insert(self, node, value):
        """Recursively inserts a node with the given value into the binary search tree."""
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert(node.left, value)
        elif value > node.value:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert(node.right, value)

    def search(self, target):
        """Searches for a node with the given target value in the binary search tree."""
        return self._search(self.root, target)

    def _search(self, node, target):
        """Recursively searches for a node with the given target value in the binary search tree."""
        if node is None:
            return False
        elif target == node.value:
            return True
        elif target < node.value and node.left is not None:
            return self._search(node.left, target)
        elif target > node.value and node.right is not None:
            return self._search(node.right, target)
        else:
            return False

    def inorder_traversal(self):
        """Performs an inorder traversal of the binary search tree and returns the values in ascending order."""
        result = []
        self._inorder_traversal(self.root, result)
        return result

    def _inorder_traversal(self, node, result):
        """Recursively performs an inorder traversal of the binary search tree."""
        if node is not None:
            self._inorder_traversal(node.left, result)
            result.append(node.value)
            self._inorder_traversal(node.right, result)

